interface.definition:
a!localVariables(
  local!activeSection: 1,
  local!activeSubsection: 1,

  local!sections: {
    a!map(
      sectionName: "Inicio",
      icon: "home",
      subsections: {
        a!map(name: "Dashboard y métricas operativas"),
        a!map(name: "Interpretación de gráficas"),
        a!map(name: "Top Remitentes")
      }
    ),
    a!map(
      sectionName: "Correos",
      icon: "envelope",
      subsections: {
        a!map(name: "Bandeja de entrada y navegación"),
        a!map(name: "Vista de detalle del correo"),
        a!map(name: "Chatbot de IA contextualizado"),
        a!map(name: "Historial de eventos"),
        a!map(name: "Comentarios y menciones"),
        a!map(name: "Gestión manual de etiquetas"),
        a!map(name: "Filtros avanzados"),
        a!map(name: "Flujo de clasificación")
      }
    ),
    a!map(
      sectionName: "Ciudadanos",
      icon: "users",
      subsections: {
        a!map(name: "Directorio de remitentes externos"),
        a!map(name: "Gestión de registros")
      }
    ),
    a!map(
      sectionName: "Organización",
      icon: "sitemap",
      subsections: {
        a!map(name: "Entidades públicas"),
        a!map(name: "Dependencias"),
        a!map(name: "Funcionarios"),
        a!map(name: "Reglas de correo")
      }
    ),
    a!map(
      sectionName: "Config. Correo",
      icon: "cog",
      subsections: {
        a!map(name: "Consola de operación"),
        a!map(name: "Bandeja (Vista Admin)"),
        a!map(name: "Categorías de etiquetas"),
        a!map(name: "Etiquetas"),
        a!map(name: "Reglas de correo"),
        a!map(name: "Estados del correo")
      }
    ),
    a!map(
      sectionName: "Config. PQRDSF",
      icon: "sliders",
      subsections: {
        a!map(name: "Tipo PQRDSF"),
        a!map(name: "Categorías PQRDSF"),
        a!map(name: "Tipo interviniente")
      }
    ),
    a!map(
      sectionName: "Config. General",
      icon: "wrench",
      subsections: {
        a!map(name: "Medios de recepción"),
        a!map(name: "Vinculación de entidad"),
        a!map(name: "Preguntas IA (Trace)")
      }
    ),
    a!map(
      sectionName: "Glosario",
      icon: "book",
      subsections: {
        a!map(name: "Términos y definiciones")
      }
    )
  },

  #"SYSTEM_SYSRULES_headerContentLayout"(
    header: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Logo",
                          labelPosition: "COLLAPSED",
                          images: { #"SYSTEM_SYSRULES_documentImage"(document: #"_a-0000ef03-0467-8000-9bf2-011c48011c48_1561798") },
                          size: "SMALL_PLUS",
                          isThumbnail: false
                        ),
                        width: "MINIMIZE"
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Manual de Usuario Operativo", size: "LARGE", color: "#FFFFFF", style: "STRONG"),
                            char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Gestión de Correos — Sede Virtual CGR  |  Supportical SPARK  |  v2.0", size: "SMALL", color: "#B0C4D8")
                          }
                        )
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Elaborado por: Diego Melo  |  Feb 2026", size: "SMALL", color: "#B0C4D8")
                          },
                          align: "RIGHT"
                        ),
                        width: "MINIMIZE"
                      )
                    },
                    alignVertical: "MIDDLE"
                  )
                }
              )
            }
          )
        },
        marginBelow: "NONE",
        style: "#1d2d44",
        showBorder: false,
        padding: "LESS"
      )
    },
    contents: {
      #"SYSTEM_SYSRULES_paneLayout"(
        panes: {

          /* ── PANEL IZQUIERDO: MENÚ ── */
          #"SYSTEM_SYSRULES_pane"(
            contents: {
              #"SYSTEM_SYSRULES_documentsChatField"(
                label: "Documents Chatbot",
                labelPosition: "ABOVE",
                documents: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6071623",
                height: "AUTO"
              ),
              #"SYSTEM_SYSRULES_forEach"(
                items: local!sections,
                expression: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: {
                      #"SYSTEM_SYSRULES_richTextIcon"(icon: fv!item.icon, size: "MEDIUM", color: "SECONDARY"),
                      "  ",
                      #"SYSTEM_SYSRULES_richTextItem_v1"(text: fn!upper(fv!item.sectionName), size: "SMALL", color: "SECONDARY", style: "STRONG")
                    },
                    marginBelow: "LESS"
                  ),
                  a!localVariables(
                    local!parentSection: fv!index,
                    #"SYSTEM_SYSRULES_forEach"(
                      items: fv!item.subsections,
                      expression: #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_sideBySideLayout"(
                            items: {
                              #"SYSTEM_SYSRULES_sideBySideItem"(
                                item: #"SYSTEM_SYSRULES_richTextDisplayField"(value: " "),
                                width: "MINIMIZE"
                              ),
                              #"SYSTEM_SYSRULES_sideBySideItem"(
                                item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: fv!item.name,
                                    size: "MEDIUM",
                                    color: if(fn!and(local!parentSection = local!activeSection, fv!index = local!activeSubsection), "ACCENT", "STANDARD"),
                                    style: if(fn!and(local!parentSection = local!activeSection, fv!index = local!activeSubsection), "STRONG", "PLAIN")
                                  )
                                )
                              ),
                              #"SYSTEM_SYSRULES_sideBySideItem"(
                                item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  value: #"SYSTEM_SYSRULES_richTextIcon"(icon: "chevron-right", color: "ACCENT"),
                                  align: "RIGHT"
                                ),
                                showWhen: fn!and(local!parentSection = local!activeSection, fv!index = local!activeSubsection),
                                width: "MINIMIZE"
                              )
                            },
                            alignVertical: "MIDDLE"
                          )
                        },
                        link: #"SYSTEM_SYSRULES_dynamicLink"(
                          saveInto: {
                            a!save(local!activeSubsection, fv!index),
                            a!save(local!activeSection, local!parentSection)
                          }
                        ),
                        marginBelow: "NONE",
                        showBorder: false,
                        padding: "LESS"
                      )
                    )
                  ),
                  #"SYSTEM_SYSRULES_richTextDisplayField"(value: " ", marginBelow: "STANDARD")
                }
              )
            },
            width: "MEDIUM",
            backgroundColor: "#f7f9fa",
            padding: "STANDARD"
          ),

          /* ── PANEL DERECHO: CONTENIDO ── */
          #"SYSTEM_SYSRULES_pane"(
            contents: {
              /* Título de sección */
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: index(local!sections.icon, local!activeSection, "book"), size: "LARGE",
                    color: "ACCENT"
                  ),
                  "  ",
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: index(local!sections.sectionName, local!activeSection, ""),
                    size: "LARGE", color: "ACCENT", style: "STRONG"
                  )
                },
                marginBelow: "LESS"
              ),
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: local!sections[local!activeSection].subsections[local!activeSubsection].name,
                contents: {
                  choose(
                    local!activeSection,

                    /* ══════════════════════════════
                       SECCIÓN 1 — INICIO
                    ══════════════════════════════ */
                    choose(
                      local!activeSubsection,

                      /* 1.1 Dashboard y métricas */
                      {
                        #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Image",
                          labelPosition: "ABOVE",
                          images: {
                            #"SYSTEM_SYSRULES_documentImage"(
                              document: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6117451"
                            )
                          },
                          size: "FIT",
                          style: "STANDARD"

                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "¿Qué es el Control Operativo?", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "La pantalla de Inicio muestra el tablero denominado ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Control Operativo", style: "STRONG"),
                            ", diseñado para ofrecer una visión panorámica e inmediata del estado de la operación de correos institucionales. Esta pantalla es de solo lectura y se actualiza automáticamente.",
                            char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Contadores principales", size: "MEDIUM", style: "STRONG"), char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Total correos recolectados: ", style: "STRONG"),
                            "Número acumulado de todos los mensajes descargados desde Outlook hacia el sistema desde el inicio de operaciones (ej.: 12.394). Incluye la fecha y hora de la última sincronización automática.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Correos clasificados: ", style: "STRONG"),
                            "Total de correos procesados y etiquetados por un analista (ej.: 623). Se muestra también el número de mensajes aún pendientes de clasificar.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Correos radicados: ", style: "STRONG"),
                            "Cantidad de correos formalmente radicados en el gestor documental institucional con número de expediente asignado.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Panel de Etiquetas activas", size: "MEDIUM", style: "STRONG"), char(10), char(10),
                            "Lista todas las etiquetas configuradas con el conteo de correos que tienen esa etiqueta asignada. Permite identificar de un vistazo cuáles son las categorías con mayor volumen de mensajes. Ejemplos típicos:", char(10),
                            "• RADICAR_AUTOMÁTICO: 1.216 correos", char(10),
                            "• TIENE_ADJUNTOS: 747 correos", char(10),
                            "• CGR_GENERAL: 381 correos"
                          }
                        ),
                        #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_richTextDisplayField"(
                              value: {
                                #"SYSTEM_SYSRULES_richTextIcon"(icon: "info-circle", color: "ACCENT"), "  ",
                                #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Consejo: ", style: "STRONG"),
                                "Use los contadores para planificar la carga de trabajo diaria del equipo. Un volumen pendiente alto puede indicar la necesidad de ajustar las cuotas de analistas en la Consola de Operación."
                              }
                            )
                          },
                          style: "#e8f4fd", showBorder: false, padding: "STANDARD"
                        )
                      },

                      /* 1.2 Interpretación de gráficas */
                      {
                        #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Image",
                          labelPosition: "ABOVE",
                          images: {
                            #"SYSTEM_SYSRULES_documentImage"(
                              document: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6118457"
                            )
                          },
                          size: "FIT",
                          style: "STANDARD",
                          isThumbnail: false
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Gráficas de volumen operativo", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Correos por mes", style: "STRONG"), char(10),
                            "Gráfica de barras o líneas con la evolución histórica mensual del total de mensajes recibidos. Es útil para:", char(10),
                            "• Identificar tendencias de crecimiento o decrecimiento en el volumen.", char(10),
                            "• Detectar picos estacionales asociados a fechas clave institucionales.", char(10),
                            "• Justificar ajustes de capacidad operativa ante la dirección.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Correos del mes actual", style: "STRONG"), char(10),
                            "Distribución diaria de correos en el mes en curso. Permite:", char(10),
                            "• Controlar el ritmo operativo semana a semana.", char(10),
                            "• Identificar días de mayor demanda para reforzar el equipo de analistas.", char(10),
                            "• Comparar el comportamiento actual versus el histórico del mismo mes."
                          }
                        )
                      },

                      /* 1.3 Top Remitentes */
                      {
                        #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Image",
                          labelPosition: "ABOVE",
                          images: {
                            #"SYSTEM_SYSRULES_documentImage"(
                              document: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6118496"
                            )
                          },
                          size: "FIT",
                          style: "STANDARD",
                          isThumbnail: false
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Top Remitentes por volumen", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "Ranking de los ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "10 remitentes", style: "STRONG"),
                            " con mayor número de mensajes enviados a la CGR en el periodo. Su utilidad principal es:", char(10), char(10),
                            "• Identificar entidades o personas con comunicación frecuente que podrían requerir reglas automáticas de clasificación para agilizar su tratamiento.", char(10),
                            "• Detectar posibles remitentes de spam o correos masivos que ameriten una regla de filtrado.", char(10),
                            "• Priorizar la configuración de etiquetas y dependencias de destino para los remitentes más activos.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Acción recomendada: ", style: "STRONG"),
                            "Si un remitente aparece consistentemente en el top 3, evalúe con el administrador si debe crearse una regla RADICAR_AUTOMÁTICO para su dominio."
                          }
                        )
                      }
                    ),

                    /* ══════════════════════════════
                       SECCIÓN 2 — CORREOS
                    ══════════════════════════════ */
                    choose(
                      local!activeSubsection,

                      /* 2.1 Bandeja de entrada */
                      {
                        #"SYSTEM_SYSRULES_imageField_v1"(
                          label: "Image",
                          labelPosition: "ABOVE",
                          images: {
                            #"SYSTEM_SYSRULES_documentImage"(
                              document: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6118439"
                            )
                          },
                          size: "FIT",
                          style: "STANDARD",
                          isThumbnail: false
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Bandeja de Entrada — Módulo principal de trabajo", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "Al ingresar al módulo ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "CORREOS", style: "STRONG"),
                            " se despliega la bandeja de entrada con la lista completa de correos recibidos. Cada fila representa un mensaje e incluye los siguientes elementos:", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Avatar / Iniciales:", style: "STRONG"), " Círculo de color con las iniciales del remitente. El color puede indicar el tipo o estado.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Ícono de clip:", style: "STRONG"), " Indica la presencia de archivos adjuntos vinculados al gestor documental.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Asunto:", style: "STRONG"), " Título o tema principal del mensaje. Si el texto es largo aparece truncado.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Remitente:", style: "STRONG"), " Dirección de correo electrónico de origen.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Fecha:", style: "STRONG"), " Fecha de recepción del mensaje (ej.: Jan 15).", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Paginación:", style: "STRONG"), char(10),
                            "La navegación entre páginas se controla mediante los botones ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "<< < 1–50 DE 12394 > >>", style: "STRONG"),
                            " en la parte superior. Cada página carga ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "50 mensajes", style: "STRONG"), "."
                          }
                        )
                      },

                      /* 2.2 Vista de detalle */
                      {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Vista de Detalle del Correo", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "Al hacer clic sobre cualquier correo de la bandeja se abre su vista de detalle. Esta pantalla está organizada en zonas funcionales:", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Panel central (izquierda):", style: "STRONG"), " Muestra el cuerpo completo del mensaje con formato de texto enriquecido.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Panel de adjuntos:", style: "STRONG"), " Accesible desde el ícono de clip. Los archivos están vinculados al gestor documental y se descargan desde allí.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Panel derecho superior:", style: "STRONG"), " Historial de eventos y opciones de suscripción al correo.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Panel derecho inferior:", style: "STRONG"), " Campo de comentarios y Chatbot de IA.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Botón rojo Clasificar:", style: "STRONG"), " Ubicado en la parte superior de la vista. Activa el flujo formal de clasificación del mensaje.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Nota importante:", style: "STRONG"),
                            " Ninguna acción realizada en la vista de detalle (leer, comentar, etiquetar) marca el correo como 'Clasificado'. Solo el botón rojo Clasificar completa el proceso formal."
                          }
                        )
                      },

                      /* 2.3 Chatbot IA */
                      {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Chatbot de IA Contextualizado", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "Cada correo abierto dispone de un ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "asistente de inteligencia artificial integrado", style: "STRONG"),
                            ", contextualizado automáticamente con el contenido del mensaje activo.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "¿Qué puede hacer con el chatbot?", style: "STRONG"), char(10),
                            "• Obtener un resumen ejecutivo del correo sin necesidad de leerlo completo.", char(10),
                            "• Consultar si el mensaje corresponde a una tipología conocida (PQRDSF, notificación judicial, comunicación administrativa, etc.).", char(10),
                            "• Recibir recomendaciones de etiqueta y dependencia destino basadas en el contenido.", char(10),
                            "• Realizar preguntas en lenguaje natural (ej.: '¿Quién firma este documento?', '¿Cuál es el número de radicado mencionado?').", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Cómo usar el chatbot:", style: "STRONG"), char(10),
                            "1. Abra el correo deseado desde la bandeja de entrada.", char(10),
                            "2. Localice el campo de texto del asistente en el panel derecho inferior.", char(10),
                            "3. Escriba su pregunta o solicitud en lenguaje natural.", char(10),
                            "4. Presione Enter o el botón de envío. La respuesta aparecerá en el hilo de conversación.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "⚠ Importante:", color: "#C00000", style: "STRONG"),
                            " Todas las preguntas realizadas al chatbot quedan registradas automáticamente en el módulo ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Preguntas IA", style: "STRONG"),
                            " (sección 10.3) para auditoría y trazabilidad.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "💡 Consejo:", style: "STRONG"),
                            " Use el chatbot para agilizar la clasificación de correos con contenido extenso o técnico. Sus sugerencias son orientativas; la decisión final siempre recae en el analista."
                          }
                        )
                      },

                      /* 2.4 Historial de eventos */
                      {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Historial de Eventos — Trazabilidad completa", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "El historial de eventos es el ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "registro de auditoría", style: "STRONG"),
                            " de cada correo. Se encuentra en el panel superior derecho de la vista de detalle y puede desplegarse o contraerse mediante el ícono de flecha (∨).", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Cada entrada del historial registra:", style: "STRONG"), char(10),
                            "• Nombre y apellido del funcionario que realizó la acción.", char(10),
                            "• Tipo de acción: etiqueta añadida, etiqueta eliminada, estado cambiado, comentario registrado, correo clasificado, correo radicado.", char(10),
                            "• Fecha y hora exacta de la acción (ej.: Feb 26, 2026 3:50 PM).", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Controles de visualización:", style: "STRONG"), char(10),
                            "• El control ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "New To Old", style: "STRONG"), " ordena de más reciente a más antiguo o viceversa.", char(10),
                            "• El botón ", #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Filters", style: "STRONG"), " acota la visualización por tipo de evento.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Ejemplos típicos de entradas en el historial:", style: "STRONG"), char(10),
                            "• 'Diego Melo — Etiqueta Arauca añadida'", char(10),
                            "• 'Sergio Bermeo — Etiqueta Valle del Cauca eliminada'", char(10),
                            "• 'Sistema — Correo radicado automáticamente con número 2025EE0002742'"
                          }
                        )
                      },

                      /* 2.5 Comentarios y menciones */
                      {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Panel de Comentarios y Menciones", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
