                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Agregar comentario:", style: "STRONG"), " Escriba su anotación en el campo 'Add a comment with @ to mention someone' y presione Enter.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Menciones (@):", style: "STRONG"), " Escriba @ seguido del nombre del funcionario para notificarlo directamente. El sistema enviará una alerta al usuario mencionado.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Hilo de respuestas:", style: "STRONG"), " Cada comentario puede recibir respuestas de otros funcionarios, creando un hilo de conversación vinculado al correo.", char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "• Visualización:", style: "STRONG"), " Los comentarios se muestran con el avatar, nombre del autor, fecha y hora.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "⚠ Nota:", color: "#C00000", style: "STRONG"),
