                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Flujo de Clasificación — Cierre formal del ciclo de vida", size: "MEDIUM_PLUS", style: "STRONG"), char(10), char(10),
                            "La clasificación es la acción formal que cierra el ciclo de vida de un correo dentro del flujo operativo.", char(10), char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(text: "Paso a paso para clasificar un correo:", style: "STRONG"), char(10),
                            "1. Abra el correo desde la bandeja de entrada.", char(10),
                            "2. Revise el contenido, adjuntos, historial de eventos y sugerencias del chatbot.", char(10),
